import { useState, useEffect, useRef } from "react";

// ── Ninja level images (cropped from 2x2 grid) ───────────────────────────────
// Top-left=Wood, Top-right=Iron, Bottom-left=Gold, Bottom-right=Obsidian
const IMGS = {
  Wood:     "data:image/jpeg;base64,",
  Iron:     "data:image/jpeg;base64,",
  Gold:     "data:image/jpeg;base64,",
  Obsidian: "data:image/jpeg;base64,",
};

// ── Constants ─────────────────────────────────────────────────────────────────
const SLOTS   = 5;
const MAX_HAND = 5;
const REFILL  = 2;
const INIT_HAND = 3;
const NINJA_HIT_TARGET = 5; // ninja always wins at 5 hits

const LEVELS = [
  { name: "Wood",     hitTarget: 5,  color: "#8B5E3C", glow: "#c47c3c", cards: ["A","B"] },
  { name: "Iron",     hitTarget: 7,  color: "#6B7FA3", glow: "#8aaed4",
    cards: ["A","A","B","B","S"] },
  { name: "Gold",     hitTarget: 9,  color: "#C9A84C", glow: "#f0d060",
    cards: ["A","A","A","B","B","B","B","S","S","D"] },
  { name: "Obsidian", hitTarget: 12, color: "#7C3AED", glow: "#a855f7",
    cards: ["A","A","A","B","B","B","S","S","D","W"] },
];

const C = {
  bg: "#0a0a0f", panel: "#12121a", border: "#2a2a3a",
  text: "#e8e4d8", dim: "#6b6875",
  red: "#e05050", green: "#50c878", blue: "#5090e0", gold: "#d4a832",
};

const CARD_LABEL = { A: "⚔", B: "🛡", S: "🌟", D: "⚡⚡", W: "🌊" };
const CARD_DESC  = { A: "Attack", B: "Block", S: "Shuriken", D: "Double Strike", W: "Like Water" };
const CARD_COLOR = { A: C.red, B: C.blue, S: "#e0a020", D: "#e0b020", W: "#20c0e0" };
const ATTACKS    = new Set(["A","S","D"]); // cards that count as attacks for cascade cancellation

// ── Helpers ───────────────────────────────────────────────────────────────────
const rnd = (arr) => arr[Math.floor(Math.random() * arr.length)];
const drawCard = (cs) => rnd(cs);
const initHand = (cs) => Array.from({ length: INIT_HAND }, () => drawCard(cs));
const refillHand = (hand, cs, bonusRefill = 0, guaranteedB = false) => {
  const h = [...hand]; let added = 0;
  const limit = REFILL + bonusRefill;
  if (guaranteedB && h.length < MAX_HAND) { h.push("B"); added++; }
  while (h.length < MAX_HAND && added < limit) { h.push(drawCard(cs)); added++; }
  return h;
};
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
  return a;
}
function nextAttack(board, from, cancelled) {
  for (let i = from + 1; i < SLOTS; i++) {
    if (ATTACKS.has(board[i]) && !cancelled.has(i)) return i;
  }
  return null;
}

// ── Round resolution ──────────────────────────────────────────────────────────
function resolveRound(pb0, nb0) {
  const pb = [...pb0];
  const nb = [...nb0];
  let pH = 0, nH = 0;
  const pC = new Set(), nC = new Set();
  const log = [];

  // Check if either side played W (Like Water) — immune entire board
  const pW = pb.includes("W");
  const nW = nb.includes("W");

  // Blocker cards: B and S both block attacks
  const isBlock = (c) => c === "B" || c === "S";
  // Attack cards that can be blocked/cascade
  const isAtk   = (c) => c === "A" || c === "S" || c === "D";

  function resolveBackdatedA(slot, myBoard, oppBoard, myC, oppC, iAmPlayer) {
    const opp = oppC.has(slot) ? null : oppBoard[slot];
    const who = iAmPlayer ? "Your" : "Ninja";
    // W immunity check
    if (iAmPlayer && nW) { myBoard[slot] = null; return; }
    if (!iAmPlayer && pW) { myBoard[slot] = null; return; }
    if (!opp) {
      if (iAmPlayer) pH++; else nH++;
      log.push(`Slot ${slot+1}: ${who} A (from clash) hits!`);
    } else if (opp === "A" || opp === "S") {
      log.push(`Slot ${slot+1}: ${who} A (from clash) — clash, no damage`);
    } else if (isBlock(opp)) {
      const x = nextAttack(myBoard, slot, myC);
      if (x !== null) myC.add(x);
      log.push(`Slot ${slot+1}: ${who} A (from clash) BLOCKED${x!==null?` — ${iAmPlayer?"your":"ninja"} slot ${x+1} cancelled`:""}`);
    }
    myBoard[slot] = null;
  }

  for (let s = 0; s < SLOTS; s++) {
    const p = pC.has(s) ? null : pb[s];
    const n = nC.has(s) ? null : nb[s];

    // ── D resolution ──────────────────────────────────────────────────────────
    if (p === "D" || n === "D") {
      const pHasD   = p === "D";
      const myBoard  = pHasD ? pb : nb;
      const oppBoard = pHasD ? nb : pb;
      const myC      = pHasD ? pC : nC;
      const oppC     = pHasD ? nC : pC;
      const who      = pHasD ? "Your" : "Ninja";
      const meW      = pHasD ? pW : nW;
      const oppW     = pHasD ? nW : pW;

      const opp0 = oppC.has(s)   ? null : oppBoard[s];
      const opp1 = (s+1 < SLOTS) ? (oppC.has(s+1) ? null : oppBoard[s+1]) : null;

      // Opponent W: D is evaded
      if (oppW) {
        myBoard[s] = null; myBoard[s+1] = null;
        log.push(`Slot ${s+1}: ${who} Double Strike evaded by Like Water`);
      } else if (isBlock(opp0) || isBlock(opp1)) {
        const bSlot = isBlock(opp0) ? s : s+1;
        myBoard[s] = null; myBoard[s+1] = null;
        oppBoard[bSlot] = null;
        const x = nextAttack(myBoard, s+1, myC);
        if (x !== null) myC.add(x);
        log.push(`Slot ${s+1}: ${who} Double Strike BLOCKED${x!==null?` — ${pHasD?"your":"ninja"} slot ${x+1} cancelled`:""}`);
      } else if (opp0 === "D" || opp1 === "D") {
        const clashSlot = opp0 === "D" ? s : s+1;
        const myOther   = clashSlot === s ? s+1 : s;
        const oppOther  = clashSlot + 1;
        myBoard[s] = null; myBoard[s+1] = null;
        oppBoard[clashSlot] = null;
        if (clashSlot+1 < SLOTS) oppBoard[clashSlot+1] = null;
        myBoard[myOther] = "A";
        if (oppOther < SLOTS) oppBoard[oppOther] = "A";
        log.push(`Slot ${s+1}: D vs D clash — ${who} A→slot ${myOther+1}, opp A→slot ${oppOther+1}`);
        if (myOther <= s) resolveBackdatedA(myOther, myBoard, oppBoard, myC, oppC, pHasD);
        if (oppOther <= s && oppOther < SLOTS) resolveBackdatedA(oppOther, oppBoard, myBoard, oppC, myC, !pHasD);
      } else if (opp0 === "A" || opp1 === "A") {
        const clashSlot = opp0 === "A" ? s : s+1;
        const myOther   = clashSlot === s ? s+1 : s;
        myBoard[s] = null; myBoard[s+1] = null;
        oppBoard[clashSlot] = null;
        myBoard[myOther] = "A";
        log.push(`Slot ${s+1}: ${who} D clashes with A — D→A at slot ${myOther+1}`);
        if (myOther <= s) resolveBackdatedA(myOther, myBoard, oppBoard, myC, oppC, pHasD);
      } else {
        myBoard[s] = null; myBoard[s+1] = null;
        if (!oppW) { if (pHasD) pH += 3; else nH += 3; }
        log.push(`Slot ${s+1}: ${who} Double Strike — 3 hits!`);
      }
      continue;
    }

    // ── A resolution ──────────────────────────────────────────────────────────
    if (p === "A") {
      if (nW) { log.push(`Slot ${s+1}: Your attack evaded by Like Water`); }
      else if (!n)          { pH++; log.push(`Slot ${s+1}: Your attack hits!`); }
      else if (n === "A")   { log.push(`Slot ${s+1}: ⚔ Sword clash — no damage`); }
      else if (n === "S")   { log.push(`Slot ${s+1}: ⚔ Clash — no damage`); }
      else if (isBlock(n))  {
        const x = nextAttack(pb, s, pC);
        if (x !== null) pC.add(x);
        log.push(`Slot ${s+1}: Your attack BLOCKED${x!==null?` — your slot ${x+1} cancelled`:""}`);
      }
      continue;
    }
    if (n === "A") {
      if (pW) { log.push(`Slot ${s+1}: Ninja attack evaded by Like Water`); }
      else if (!p)          { nH++; log.push(`Slot ${s+1}: Ninja attack hits you!`); }
      else if (isBlock(p))  {
        const x = nextAttack(nb, s, nC);
        if (x !== null) nC.add(x);
        log.push(`Slot ${s+1}: Ninja attack BLOCKED${x!==null?` — ninja slot ${x+1} cancelled`:""}`);
      }
      continue;
    }

    // ── S resolution ──────────────────────────────────────────────────────────
    if (p === "S") {
      if (nW) { log.push(`Slot ${s+1}: Your shuriken evaded by Like Water`); }
      else if (!n)         { pH++; log.push(`Slot ${s+1}: Your shuriken hits!`); }
      else if (n === "S")  { log.push(`Slot ${s+1}: Shuriken clash — no damage`); }
      else if (n === "A")  {
        // S blocks A
        const x = nextAttack(nb, s, nC);
        if (x !== null) nC.add(x);
        log.push(`Slot ${s+1}: Your shuriken blocks ninja's attack${x!==null?` — ninja slot ${x+1} cancelled`:""}`);
      }
      else if (n === "B")  { log.push(`Slot ${s+1}: Shuriken vs Block — no effect`); }
      continue;
    }
    if (n === "S") {
      if (pW) { log.push(`Slot ${s+1}: Ninja shuriken evaded by Like Water`); }
      else if (!p)         { nH++; log.push(`Slot ${s+1}: Ninja shuriken hits you!`); }
      else if (p === "A")  {
        const x = nextAttack(pb, s, pC);
        if (x !== null) pC.add(x);
        log.push(`Slot ${s+1}: Ninja shuriken blocks your attack${x!==null?` — your slot ${x+1} cancelled`:""}`);
      }
      else if (p === "B")  { log.push(`Slot ${s+1}: Block vs Shuriken — no effect`); }
      continue;
    }

    // ── B resolution ──────────────────────────────────────────────────────────
    if (p === "B" && n === "B") { log.push(`Slot ${s+1}: Block vs Block — no effect`); }
    // W vs anything: already handled by immunity above; remaining combos are inert
  }
  return { pH, nH, log };
}

// ── AI ────────────────────────────────────────────────────────────────────────
function aiPlay(hand, level, prevP) {
  const board = Array(SLOTS).fill(null);
  const used = [];

  const place = (card, slot) => {
    if (board[slot] !== null) return false;
    board[slot] = card;
    const idx = hand.findIndex((c,i) => c===card && !used.includes(i));
    if (idx >= 0) used.push(idx);
    return true;
  };

  if (level === 0) {
    // Random
    const n = 1 + Math.floor(Math.random() * hand.length);
    const slots = shuffle([0,1,2,3,4]).slice(0, n);
    const cards = shuffle(hand.map((_,i)=>i)).slice(0, n);
    cards.forEach((ci, i) => { board[slots[i]] = hand[ci]; used.push(ci); });

  } else if (level === 1) {
    // Iron: prefer blocking player's previous attacks
    const prevAtks = prevP ? prevP.map((c,i)=>c==="A"?i:-1).filter(i=>i>=0) : [];
    const bIdxs = hand.map((c,i)=>c==="B"?i:-1).filter(i=>i>=0);
    const aIdxs = hand.map((c,i)=>c==="A"?i:-1).filter(i=>i>=0);
    bIdxs.slice(0,2).forEach(bi => {
      const t = prevAtks.find(s => board[s]===null);
      if (t !== undefined) { board[t] = "B"; used.push(bi); }
    });
    const free = [0,1,2,3,4].filter(s=>board[s]===null);
    aIdxs.forEach(ai => {
      if (free.length > 0 && Math.random() > 0.4) {
        const s = free.shift(); board[s] = "A"; used.push(ai);
      }
    });

  } else if (level === 2) {
    // Gold: tactical D placement + late blocks
    const dIdxs = hand.map((c,i)=>c==="D"?i:-1).filter(i=>i>=0);
    const bIdxs = hand.map((c,i)=>c==="B"?i:-1).filter(i=>i>=0);
    const aIdxs = hand.map((c,i)=>c==="A"?i:-1).filter(i=>i>=0);
    if (dIdxs.length > 0 && Math.random() > 0.3) {
      const st = Math.random() > 0.5 ? 0 : 2;
      if (!board[st] && !board[st+1]) { board[st]="D"; board[st+1]="D_c"; used.push(dIdxs[0]); }
    }
    bIdxs.slice(0,2).forEach(bi => {
      const s = [3,4,2].find(x=>board[x]===null);
      if (s!==undefined) { board[s]="B"; used.push(bi); }
    });
    aIdxs.forEach(ai => {
      const s = [0,1,2,3,4].find(x=>board[x]===null);
      if (s!==undefined) { board[s]="A"; used.push(ai); }
    });

  } else {
    // Obsidian: near-optimal
    const dN = hand.filter(c=>c==="D").length;
    const bN = hand.filter(c=>c==="B").length;
    const aN = hand.filter(c=>c==="A").length;
    const sN = hand.filter(c=>c==="S").length;
    const wN = hand.filter(c=>c==="W").length;
    // Decide whether to play W this round (prefer W when hits are ahead, defensive)
    const playW = wN > 0 && Math.random() > 0.5;
    if (dN > 0 && !playW) { board[0]="D"; board[1]="D_c"; used.push(hand.findIndex(c=>c==="D")); }
    if (playW) {
      // W round: only B and W allowed (no S, A, or D)
      const wi = hand.findIndex(c=>c==="W"); board[2]="W"; used.push(wi);
      let bC = 0;
      [0,1,3,4].filter(s=>board[s]===null).forEach(s => {
        if (bC < bN) { board[s]="B"; used.push(hand.findIndex((c,i)=>c==="B"&&!used.includes(i))); bC++; }
      });
    } else {
      // Normal round: A, B, S, D — no W, and S is allowed
      let aC = 0;
      [1,2,3].filter(s=>board[s]===null).forEach(s => {
        if (aC < aN) { board[s]="A"; used.push(hand.findIndex((c,i)=>c==="A"&&!used.includes(i))); aC++; }
      });
      let sC = 0;
      [0,4].filter(s=>board[s]===null).forEach(s => {
        if (sC < sN) { board[s]="S"; used.push(hand.findIndex((c,i)=>c==="S"&&!used.includes(i))); sC++; }
      });
      let bC = 0;
      [4,3,2].filter(s=>board[s]===null).forEach(s => {
        if (bC < bN) { board[s]="B"; used.push(hand.findIndex((c,i)=>c==="B"&&!used.includes(i))); bC++; }
      });
    }
  }

  // ── Minimum play guarantee ────────────────────────────────────────────────
  // If hand has 5: must play at least 2. If hand has 4: must play at least 1.
  const minPlay = hand.length === 5 ? 2 : hand.length === 4 ? 1 : 0;
  const played = board.filter(c => c !== null && c !== "D_c").length;
  if (played < minPlay) {
    const hasW = board.includes("W");
    const hasS = board.some(c => c === "S");
    const unused = hand.map((_,i) => i).filter(i => !used.includes(i));
    const freeSlots = shuffle([0,1,2,3,4].filter(s => board[s] === null));
    shuffle(unused).forEach(ci => {
      if (board.filter(c=>c&&c!=="D_c").length >= minPlay) return;
      if (freeSlots.length === 0) return;
      const card = hand[ci];
      // Respect W/S mutual exclusion
      if (card === "W" && hasS) return;
      if (card === "S" && hasW) return;
      if (card === "W" && board.some(c=>c==="A"||c==="S")) return;
      if ((card === "A" || card === "S") && hasW) return;
      const s = freeSlots.shift();
      board[s] = card;
      used.push(ci);
    });
  }

  const newHand = hand.filter((_,i) => {
    const p = used.indexOf(i); if (p>=0) { used[p]=-1; return false; } return true;
  });
  return { board: board.map(c => c==="D_c"?null:c), newHand };
}

// ── Sub-components ────────────────────────────────────────────────────────────
function HitBar({ label, hits, target, color }) {
  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:C.dim, marginBottom:3 }}>
        <span>{label}</span><span style={{ color }}>{hits} / {target}</span>
      </div>
      <div style={{ height:7, background:C.border, borderRadius:4, overflow:"hidden" }}>
        <div style={{ height:"100%", width:`${Math.min(100,(hits/target)*100)}%`, background:color, borderRadius:4, transition:"width 0.4s" }} />
      </div>
    </div>
  );
}

function CardChip({ card, small }) {
  if (!card || card==="D_cont") return <span style={{ color:C.dim, fontSize:12 }}>·</span>;
  return (
    <span style={{
      display:"inline-flex", alignItems:"center", justifyContent:"center",
      width:small?28:36, height:small?28:36, borderRadius:6,
      border:`1px solid ${CARD_COLOR[card]}44`, background:`${CARD_COLOR[card]}18`,
      color:CARD_COLOR[card], fontWeight:700, fontSize:small?13:18, userSelect:"none",
    }}>{CARD_LABEL[card]}</span>
  );
}

function HandCard({ card, selected, onClick }) {
  return (
    <div onClick={onClick} style={{
      width:52, height:68, borderRadius:10,
      border:`2px solid ${selected?CARD_COLOR[card]:C.border}`,
      background:selected?`${CARD_COLOR[card]}22`:C.panel,
      display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:4,
      cursor:"pointer", transition:"border-color 0.15s, transform 0.1s",
      transform:selected?"translateY(-4px)":"none",
      boxShadow:selected?`0 4px 12px ${CARD_COLOR[card]}44`:"none",
    }}>
      <span style={{ fontSize:20 }}>{CARD_LABEL[card]}</span>
      <span style={{ fontSize:9, color:C.dim }}>{CARD_DESC[card]}</span>
    </div>
  );
}

function BoardRow({ label, board, revealed, color }) {
  const borderColor = color || C.border;
  return (
    <div>
      <div style={{ fontSize:10, color:C.dim, marginBottom:4, textTransform:"uppercase", letterSpacing:2 }}>{label}</div>
      <div style={{ display:"flex", gap:6 }}>
        {board.map((card, i) => {
          const show = revealed && card && card !== "D_cont";
          return (
            <div key={i} style={{
              flex:1, height:52, borderRadius:8,
              background:show?`${CARD_COLOR[card]}18`:C.panel,
              border:`1px solid ${show?CARD_COLOR[card]+"44":borderColor+"33"}`,
              display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:2,
            }}>
              <span style={{ fontSize:10, color:C.dim }}>{i+1}</span>
              {show ? <CardChip card={card} small />
                : !revealed && card ? <span style={{ fontSize:16 }}>▪</span> : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const btnS = (color, disabled) => ({
  flex:1, padding:"10px 0", borderRadius:8, border:`1px solid ${color}44`,
  background:"transparent", color:disabled?"#444":color,
  cursor:disabled?"not-allowed":"pointer", fontSize:13, fontWeight:600,
  opacity:disabled?0.5:1,
});

// ── Level select ──────────────────────────────────────────────────────────────
function LevelSelect({ beaten, onSelect }) {
  return (
    <div style={{ textAlign:"center", padding:"24px 16px" }}>
      <div style={{ color:C.dim, fontSize:12, letterSpacing:4, textTransform:"uppercase", marginBottom:6 }}>Subgame</div>
      <div style={{ color:C.text, fontSize:28, fontFamily:"Georgia, serif", fontWeight:700, marginBottom:4 }}>Ninja Dummy</div>
      <div style={{ color:C.dim, fontSize:12, marginBottom:28, fontStyle:"italic" }}>Defeat all four to claim your reward</div>
      <div style={{ display:"flex", gap:14, justifyContent:"center", flexWrap:"wrap" }}>
        {LEVELS.map((lv, i) => {
          const locked = i > 0 && !beaten.has(i - 1);
          const done   = beaten.has(i);
          return (
            <div key={lv.name} onClick={() => !locked && onSelect(i)}
              style={{
                width:130, borderRadius:12, overflow:"hidden",
                border:`2px solid ${done?lv.glow:locked?"#333":lv.color}`,
                background:locked?"#111":"#16161f",
                cursor:locked?"not-allowed":"pointer", opacity:locked?0.45:1,
                transition:"transform 0.15s, box-shadow 0.15s",
                boxShadow:done?`0 0 18px ${lv.glow}55`:"none",
              }}
              onMouseEnter={e=>{ if(!locked) e.currentTarget.style.transform="translateY(-3px)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.transform="none"; }}
            >
              <img src={IMGS[lv.name]} alt={lv.name}
                style={{ width:"100%", height:110, objectFit:"cover", display:"block" }} />
              <div style={{ padding:"8px 10px 10px" }}>
                <div style={{ color:done?lv.glow:locked?C.dim:C.text, fontWeight:700, fontSize:14 }}>
                  {done?"✓ ":locked?"🔒 ":""}{lv.name}
                </div>
                <div style={{ color:C.dim, fontSize:11, marginTop:2 }}>
                  {locked ? "Locked" : `You need ${lv.hitTarget} · Ninja needs ${NINJA_HIT_TARGET}`}
                </div>
                {i >= 1 && !locked && (
                  <div style={{ color:"#e0a02066", fontSize:10, marginTop:3 }}>
                    {i === 1 ? "+ Shuriken" : i === 2 ? "+ Shuriken, D-Strike" : "+ Shuriken, D-Strike, Water"}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
      {beaten.size === 4 && (
        <div style={{ marginTop:24, padding:"12px 20px", background:"#d4a83222",
          border:"1px solid #d4a832", borderRadius:8, color:C.gold, fontSize:15, fontWeight:700 }}>
          🏆 All Ninja Dummies defeated! Your reward awaits.
        </div>
      )}
    </div>
  );
}

// ── Main ──────────────────────────────────────────────────────────────────────
export default function NinjaDummy({ onReward, onExit }) {
  const [screen,      setScreen]      = useState("select");
  const [levelIdx,    setLevelIdx]    = useState(0);
  const [beaten,      setBeaten]      = useState(new Set());

  const [playerHand,  setPlayerHand]  = useState([]);
  const [ninjaHand,   setNinjaHand]   = useState([]);
  const [playerBoard, setPlayerBoard] = useState(Array(SLOTS).fill(null));
  const [ninjaBoard,  setNinjaBoard]  = useState(Array(SLOTS).fill(null));
  const [playerHits,  setPlayerHits]  = useState(0);
  const [ninjaHits,   setNinjaHits]   = useState(0);
  const [roundLog,    setRoundLog]    = useState([]);
  const [roundNo,     setRoundNo]     = useState(1);
  const [phase,       setPhase]       = useState("place"); // place | reveal | done
  const [winner,      setWinner]      = useState(null);
  const [prevPB,      setPrevPB]      = useState(null);
  const [selCard,     setSelCard]     = useState(null);
  const logRef = useRef(null);

  const lv = LEVELS[levelIdx];
  const cs = lv.cards;

  function comboBonus(hits, cardsPlayed) {
    if (hits === 0) return { bonusHits: 0, bonusRefill: 0, guaranteedB: false };
    if (cardsPlayed === 5) return { bonusHits: 1, bonusRefill: 1, guaranteedB: true };
    if (cardsPlayed === 4) return { bonusHits: 1, bonusRefill: 0, guaranteedB: false };
    return { bonusHits: 0, bonusRefill: 0, guaranteedB: false };
  }

  function startLevel(idx) {
    const c = LEVELS[idx].cards;
    setLevelIdx(idx);
    setPlayerHand(initHand(c)); setNinjaHand(initHand(c));
    setPlayerBoard(Array(SLOTS).fill(null)); setNinjaBoard(Array(SLOTS).fill(null));
    setPlayerHits(0); setNinjaHits(0);
    setRoundLog([]); setRoundNo(1); setPhase("place");
    setWinner(null); setPrevPB(null); setSelCard(null);
    setScreen("play");
  }

  function placeCard(slotIdx) {
    if (phase !== "place" || selCard === null) return;
    const card = playerHand[selCard];
    // W restriction: if W is being played, check no A or S already on board
    if (card === "W") {
      const hasAorS = playerBoard.some(c => c === "A" || c === "S");
      if (hasAorS) return;
    }
    // If A or S being placed, check no W already on board
    if ((card === "A" || card === "S") && playerBoard.includes("W")) return;
    if (card === "D") {
      if (slotIdx >= SLOTS - 1 || playerBoard[slotIdx] || playerBoard[slotIdx+1]) return;
      const nb = [...playerBoard]; nb[slotIdx]="D"; nb[slotIdx+1]="D_cont";
      setPlayerBoard(nb);
    } else {
      if (playerBoard[slotIdx]) return;
      const nb = [...playerBoard]; nb[slotIdx] = card; setPlayerBoard(nb);
    }
    const nh = [...playerHand]; nh.splice(selCard, 1); setPlayerHand(nh);
    setSelCard(null);
  }

  function clearBoard() {
    const played = playerBoard.filter(c => c && c!=="D_cont");
    setPlayerBoard(Array(SLOTS).fill(null));
    setPlayerHand(h => [...h, ...played].slice(0, MAX_HAND));
    setSelCard(null);
  }

  function submitRound() {
    if (phase !== "place") return;
    const cleanPB = playerBoard.map(c => c==="D_cont"?null:c);
    const pCardsPlayed = cleanPB.filter(Boolean).length;
    const { board: nb, newHand: nh } = aiPlay(ninjaHand, levelIdx, prevPB);
    const nCardsPlayed = nb.filter(Boolean).length;
    const { pH, nH, log } = resolveRound(cleanPB, nb);

    // Combo bonuses
    const pCombo = comboBonus(pH, pCardsPlayed);
    const nCombo = comboBonus(nH, nCardsPlayed);
    const finalPH = pH + pCombo.bonusHits;
    const finalNH = nH + nCombo.bonusHits;
    const fullLog = [...log];
    if (pCombo.bonusHits > 0) fullLog.push(`⚡ Combo! You played ${pCardsPlayed} cards and scored — +${pCombo.bonusHits} hit${pCombo.guaranteedB?" + bonus B next round":""}`);
    if (nCombo.bonusHits > 0) fullLog.push(`⚡ Ninja combo! +${nCombo.bonusHits} hit${nCombo.guaranteedB?" + ninja draws bonus B":""}`);

    const newPH = playerHits + finalPH, newNH = ninjaHits + finalNH;
    setNinjaBoard(nb); setNinjaHand(nh); setRoundLog(fullLog); setPhase("reveal"); setPrevPB(cleanPB);
    setTimeout(() => {
      setPlayerHits(newPH); setNinjaHits(newNH);
      if (newPH >= lv.hitTarget || newNH >= NINJA_HIT_TARGET) {
        const w = newPH >= lv.hitTarget ? "player" : "ninja";
        setWinner(w); setPhase("done");
        if (w === "player") {
          const nb2 = new Set(beaten); nb2.add(levelIdx); setBeaten(nb2);
          if (nb2.size === 4 && onReward) onReward();
        }
      } else {
        setPlayerHand(h => refillHand(h, cs, pCombo.bonusRefill, pCombo.guaranteedB));
        setNinjaHand(h => refillHand(h, cs, nCombo.bonusRefill, nCombo.guaranteedB));
        setPlayerBoard(Array(SLOTS).fill(null)); setNinjaBoard(Array(SLOTS).fill(null));
        setRoundNo(r => r+1); setPhase("place"); setSelCard(null);
      }
    }, 1800);
  }

  useEffect(() => { if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight; }, [roundLog]);

  if (screen === "select") return (
    <div style={{ background:C.bg, minHeight:"100vh", fontFamily:"'Segoe UI',system-ui,sans-serif", color:C.text }}>
      {onExit && (
        <div style={{ display:"flex", justifyContent:"flex-end", padding:"12px 16px 0" }}>
          <button onClick={onExit} style={{ background:"none", border:`1px solid ${C.border}`, color:C.dim, cursor:"pointer", fontSize:11, padding:"4px 10px", borderRadius:4 }}>✕ Exit</button>
        </div>
      )}
      <LevelSelect beaten={beaten} onSelect={startLevel} />
    </div>
  );

  return (
    <div style={{ background:C.bg, minHeight:"100vh", fontFamily:"'Segoe UI',system-ui,sans-serif", color:C.text, maxWidth:540, margin:"0 auto", paddingBottom:32 }}>

      {/* Header */}
      <div style={{ display:"flex", alignItems:"center", gap:12, padding:"14px 16px 10px", borderBottom:`1px solid ${C.border}` }}>
        <button onClick={()=>setScreen("select")} style={{ background:"none", border:"none", color:C.dim, cursor:"pointer", fontSize:18, padding:0 }}>←</button>
        <img src={IMGS[lv.name]} alt={lv.name} style={{ width:40, height:40, borderRadius:8, objectFit:"cover", border:`2px solid ${lv.color}` }} />
        <div>
          <div style={{ fontSize:16, fontWeight:700, color:lv.glow }}>{lv.name} Ninja</div>
          <div style={{ fontSize:11, color:C.dim }}>You need {lv.hitTarget} hits · Ninja needs {NINJA_HIT_TARGET} · Round {roundNo}</div>
        </div>
        <div style={{ marginLeft:"auto", display:"flex", alignItems:"center", gap:10, fontSize:11, color:C.dim }}>
          {[...beaten].map(i => <span key={i} style={{ color:LEVELS[i].glow }}>✓{LEVELS[i].name[0]}</span>)}
          {onExit && <button onClick={onExit} style={{ background:"none", border:`1px solid ${C.border}`, color:C.dim, cursor:"pointer", fontSize:11, padding:"4px 10px", borderRadius:4 }}>✕ Exit</button>}
        </div>
      </div>

      {/* Hit bars */}
      <div style={{ padding:"12px 16px 0" }}>
        <HitBar label="You" hits={playerHits} target={lv.hitTarget} color={C.green} />
        <div style={{ height:6 }} />
        <HitBar label="Ninja" hits={ninjaHits} target={NINJA_HIT_TARGET} color={C.red} />
      </div>

      {/* ── 4-row layout ── */}
      <div style={{ padding:"14px 16px 0" }}>

        {/* Row 1: Ninja hand — face-down backs */}
        <div style={{ marginBottom:6 }}>
          <div style={{ fontSize:10, color:C.dim, marginBottom:4, textTransform:"uppercase", letterSpacing:2 }}>
            Ninja hand ({ninjaHand.length})
          </div>
          <div style={{ display:"flex", gap:6 }}>
            {ninjaHand.map((_, i) => (
              <div key={i} style={{
                width:36, height:50, borderRadius:8,
                background:"linear-gradient(135deg, #1a1a2e 0%, #2a1a3e 100%)",
                border:`1px solid ${lv.color}44`,
                display:"flex", alignItems:"center", justifyContent:"center",
              }}>
                <span style={{ fontSize:14, opacity:0.4 }}>🂠</span>
              </div>
            ))}
            {ninjaHand.length === 0 && <span style={{ color:C.dim, fontSize:11 }}>Empty</span>}
          </div>
        </div>

        {/* Row 2: Ninja board */}
        <BoardRow label="Ninja played" board={ninjaBoard} revealed={phase!=="place"} color={lv.color} />

        <div style={{ height:10, borderLeft:`2px dashed ${C.border}33`, margin:"4px 0 4px 17px" }} />

        {/* Row 3: Player board — clickable during placement */}
        <div>
          <div style={{ fontSize:10, color:C.dim, marginBottom:4, textTransform:"uppercase", letterSpacing:2 }}>
            You played{phase==="place" && selCard!==null ? " — tap a slot" : ""}
          </div>
          <div style={{ display:"flex", gap:6 }}>
            {playerBoard.map((card, s) => {
              const show = card && card !== "D_cont";
              const clickable = phase==="place" && selCard!==null;
              return (
                <div key={s} onClick={() => placeCard(s)} style={{
                  flex:1, height:52, borderRadius:8,
                  background: show ? `${CARD_COLOR[card]}18` : C.panel,
                  border: `1px solid ${clickable ? lv.glow+"88" : show ? CARD_COLOR[card]+"44" : C.green+"33"}`,
                  display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:2,
                  cursor: clickable ? "pointer" : "default",
                  transition:"border-color 0.15s",
                  boxShadow: clickable ? `0 0 6px ${lv.glow}22` : "none",
                }}>
                  <span style={{ fontSize:10, color:C.dim }}>{s+1}</span>
                  {show && <CardChip card={card} small />}
                  {card==="D_cont" && <span style={{ color:"#e0b02055", fontSize:10 }}>↩</span>}
                </div>
              );
            })}
          </div>
        </div>

        {/* Row 4: Player hand */}
        {phase==="place" && (
          <div style={{ marginTop:10 }}>
            <div style={{ fontSize:10, color:C.dim, marginBottom:6, textTransform:"uppercase", letterSpacing:2 }}>
              Your hand ({playerHand.length}) — tap a card, then tap a slot above
            </div>
            <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
              {playerHand.map((card, i) => (
                <HandCard key={i} card={card} selected={selCard===i} onClick={()=>setSelCard(selCard===i?null:i)} />
              ))}
              {playerHand.length === 0 && <span style={{ color:C.dim, fontSize:11 }}>No cards</span>}
            </div>
            {selCard !== null && (
              <div style={{ fontSize:11, color:lv.glow, marginTop:6 }}>
                {playerHand[selCard]==="D" ? "Tap the LEFT slot of two consecutive slots (Double Strike)" : "Tap a slot above to place"}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Action buttons — kept above the round log so it never gets pushed
          off-screen as the log grows. */}
      <div style={{ padding:"12px 16px 0", display:"flex", gap:8 }}>
        {phase==="place" && <>
          <button onClick={clearBoard} style={btnS(C.dim, false)}>Clear</button>
          <button onClick={submitRound} style={btnS(lv.glow, false)}>⚔ Fight Round</button>
        </>}
        {phase==="reveal" && <div style={{ color:C.dim, fontSize:12, fontStyle:"italic", padding:"10px 0" }}>Resolving…</div>}
        {phase==="done" && (
          <div style={{ width:"100%", textAlign:"center" }}>
            {winner==="player"
              ? <div style={{ color:C.green, fontSize:20, fontWeight:700, marginBottom:10 }}>⚔ Victory!</div>
              : <div style={{ color:C.red,   fontSize:20, fontWeight:700, marginBottom:10 }}>💀 Defeated!</div>}
            <div style={{ display:"flex", gap:8, justifyContent:"center" }}>
              <button onClick={()=>startLevel(levelIdx)} style={btnS(C.blue, false)}>Retry</button>
              <button onClick={()=>setScreen("select")}  style={btnS(lv.glow, false)}>Levels</button>
            </div>
          </div>
        )}
      </div>

      {/* Round log */}
      {roundLog.length > 0 && (
        <div ref={logRef} style={{ margin:"10px 16px 0", background:C.panel, borderRadius:8, border:`1px solid ${C.border}`, maxHeight:100, overflowY:"auto", padding:"8px 12px" }}>
          {roundLog.map((l,i) => <div key={i} style={{ fontSize:11, color:i===0?C.text:C.dim, lineHeight:1.6 }}>{l}</div>)}
        </div>
      )}

    </div>
  );
}
